/**
 * Streams the reference tools wrote, frozen so the tests need none of them installed. Made with
 * gzip 1.15, bzip2 1.0.8, XZ Utils 5.8.4, zstd 1.5.7, lz4 1.10.0, brotli 1.2.0 and the ncompress
 * 1.0.2 Python binding of ncompress, from the inputs `referenceInputs` builds.
 */

/**
 * The inputs: text with Polish letters, and bytes that are part noise, part runs.
 *
 * @returns {{ text: Uint8Array; noise: Uint8Array }} Both inputs.
 */
export function referenceInputs(): { text: Uint8Array; noise: Uint8Array } {
  const text = new TextEncoder().encode(
    Array.from(
      { length: 60 },
      (_, i) =>
        `Line ${i}: the quick brown fox jumps over the lazy dog, zażółć gęślą jaźń ${i * i}\n`,
    ).join(""),
  );
  const noise = new Uint8Array(2048);
  let x = 7;
  for (let i = 0; i < noise.length; i++) {
    x = (Math.imul(x, 1103515245) + 12345) >>> 0;
    noise[i] = i % 3 === 0 ? x >>> 24 : (i >>> 4) & 0xff;
  }
  return { text, noise };
}

export interface Reference {
  /** The command that wrote it. */
  tool: string;
  format: string;
  container: string;
  input: "text" | "noise";
  /** The stream, in base64. */
  data: string;
}

